fn test_clusterlaunchcontrol_response_read_without_waiting_is_an_inflight_hazard() {
    let ws = conflicts(
        &ptx!(
            parse "execution_error/clusterlaunchcontrol_response_read_without_waiting_is_an_inflight_hazard"
        ),
        AnalysisConfig::new((64, 1, 1)),
    );
    assert_any(&ws, "thread 32's read and the response write", |w| {
        w.earlier == Side::effect(0, Write, AsyncOpKind::ClcResponse) && w.later.thread == 32
    });
}

/// Two warps; thread 0 stages `scale[0]` in shared `meta`, which thread 32 reads.

fn test_cp_async_bulk_tensor_read_without_waiting_is_an_inflight_hazard() {
    let module = ptx!(parse "execution_error/cp_async_bulk_tensor_read_without_waiting_is_an_inflight_hazard");
    let mut config = AnalysisConfig::new((32, 1, 1));
    config.arrays = vec![
        ArrayDef {
            name: "in".to_string(),
            base: 0x10000,
            elem_width: 2,
            len: 64,
            kind: ArrayKind::Input,
        },
        ArrayDef {
            name: "out".to_string(),
            base: 0x20000,
            elem_width: 2,
            len: 2,
            kind: ArrayKind::Output,
        },
    ];
    config.params = vec![
        ParamValue::ArrayPtr("in".to_string()),
        ParamValue::ArrayPtr("out".to_string()),
    ];
    let ws = conflicts(&module, config);
    assert_any(&ws, "thread 0's read and the TMA copy's write", |w| {
        w.kind == ConflictKind::WriteRead
            && w.earlier.op == Some(AsyncOpKind::TensorCopy)
            && w.later == Side::plain(0, Read)
    });
}

/// A `bar.sync` after the issue orders nothing about the copy's write: warp 1, released by
/// `gate`'s bare `complete_tx`, reads `buf` unordered with it.

fn test_tcgen05_alloc_does_not_publish_its_address_write() {
    let ws = conflicts(
        &ptx!(parse "execution_error/tcgen05_alloc_address_read_without_bar_warp_sync"),
        AnalysisConfig::new((32, 1, 1)),
    );
    let readers: Vec<u32> = ws
        .iter()
        .filter(|w| {
            w.kind == ConflictKind::WriteRead
                && on_shared(w)
                && w.earlier == Side::plain(0, Write)
                && w.later.mode == Read
                && w.later.op.is_none()
        })
        .map(|w| w.later.thread)
        .collect();
    assert_eq!(
        readers,
        (1..32).collect::<Vec<u32>>(),
        "lane 0's address write unordered with each other lane's load: {ws:#?}"
    );
}

/// Thread 32's TMA reads the tensor map thread 0 is still building: both fences are there, but
/// nothing orders thread 0's release before thread 32's acquire.

fn test_tcgen05_alloc_orders_lanes_plain_accesses() {
    let mut config = AnalysisConfig::new((32, 1, 1));
    config.arrays = vec![ArrayDef {
        name: "out".to_string(),
        base: 0x20000,
        elem_width: 4,
        len: 1,
        kind: ArrayKind::Output,
    }];
    config.params = vec![ParamValue::ArrayPtr("out".to_string())];
    let ws = conflicts(
        &ptx!(parse "execution_error/tcgen05_alloc_orders_lanes_plain_accesses"),
        config,
    );
    assert_any(&ws, "lane 1's store unordered with lane 2's load", |w| {
        w.kind == ConflictKind::WriteRead
            && on_shared(w)
            && w.earlier == Side::plain(1, Write)
            && w.later == Side::plain(2, Read)
    });
}

/// Every lane loads the Tensor Memory address right after `tcgen05.alloc`, relying on the alloc
/// to synchronize the warp: lane 0 writes the address for the warp, and the alloc orders that
/// write before no other lane's load.

fn test_tcgen05_alloc_sizes_unordered() {
    let checked = check(
        &parse(&ptx!("execution_error/tcgen05_alloc_sizes_unordered")),
        None,
        AnalysisConfig::new((64, 1, 1)),
    );
    let graph = &checked.analysis.graph;
    let thread = |e| {
        graph
            .acting_thread(e)
            .expect("an allocation acts for a thread")
            .0
    };
    let pairs: Vec<(u32, u32)> = checked
        .report
        .allocation_order
        .violations()
        .iter()
        .map(|v| match *v {
            AllocationOrderViolation::Unordered { earlier, later } => {
                (thread(earlier), thread(later))
            }
            ref other => panic!("expected unordered allocations, got {other:?}"),
        })
        .collect();
    assert_eq!(pairs, [(0, 32)], "warp 0's allocation, then warp 1's");
}

fn test_tcgen05_commit_does_not_release_the_threads_earlier_store() {
    assert_meta_races(
        "tcgen05.commit",
        &ptx!(parse "execution_error/tcgen05_commit_does_not_release_the_threads_earlier_store"),
    );
}

/// `mbarrier.init` writes its object: thread 1's init of `word` is unordered with thread 0's
/// store and load of it, so `out[0]` need not read back 42.

fn test_tcgen05_dealloc_with_an_mma_in_flight_is_rejected() {
    let effects = freed_while_in_use(
        &parse(&ptx!(
            "execution_error/tcgen05_dealloc_with_an_mma_in_flight_is_rejected"
        )),
        AnalysisConfig::new((64, 1, 1)),
    );
    assert!(
        effects.contains(&Side::effect(0, Write, AsyncOpKind::Tcgen05Mma)),
        "expected the MMA's write of D freed, got: {effects:?}"
    );
}

/// A `tcgen05.wait::ld` after a `bar.sync` is no hazard by itself: the load conflicts only with
/// the store its `tcgen05.wait::st` pipelines before it, so tensor ordering passes. The kernel
/// is rejected because it never frees its 32 columns.

fn test_tcgen05_dealloc_with_an_unwaited_ld_or_st_is_rejected() {
    for (expected, (name, src)) in [
        (
            Side::effect(0, Read, AsyncOpKind::Tcgen05Ld),
            ptx_case!("execution_error/tcgen05_dealloc_with_an_unwaited_ld_or_st_is_rejected_ld"),
        ),
        (
            Side::effect(0, Write, AsyncOpKind::Tcgen05St),
            ptx_case!("execution_error/tcgen05_dealloc_with_an_unwaited_ld_or_st_is_rejected_st"),
        ),
    ] {
        let effects = freed_while_in_use(&parse(&src), AnalysisConfig::new((32, 1, 1)));
        assert!(
            effects
                .iter()
                .any(|e| e.op == expected.op && e.mode == expected.mode),
            "{name}: expected a freed {expected:?}, got: {effects:?}"
        );
    }
}

/// `tcgen05.dealloc` of `D`'s columns while the MMA writing them is still in flight -
/// committed, but no thread has observed `mma_bar` - is rejected.

fn test_tcgen05_dealloc_with_an_unwaited_ld_or_st_is_rejected() {
    for (expected, (name, src)) in [
        (
            Side::effect(0, Read, AsyncOpKind::Tcgen05Ld),
            ptx_case!("execution_error/tcgen05_dealloc_with_an_unwaited_ld_or_st_is_rejected_ld"),
        ),
        (
            Side::effect(0, Write, AsyncOpKind::Tcgen05St),
            ptx_case!("execution_error/tcgen05_dealloc_with_an_unwaited_ld_or_st_is_rejected_st"),
        ),
    ] {
        let effects = freed_while_in_use(&parse(&src), AnalysisConfig::new((32, 1, 1)));
        assert!(
            effects
                .iter()
                .any(|e| e.op == expected.op && e.mode == expected.mode),
            "{name}: expected a freed {expected:?}, got: {effects:?}"
        );
    }
}

/// `tcgen05.dealloc` of `D`'s columns while the MMA writing them is still in flight -
/// committed, but no thread has observed `mma_bar` - is rejected.

fn test_tcgen05_mma_bar_sync_before_completion_orders_nothing() {
    let ws = unproved(
        &parse(&ptx!(
            "execution_error/tcgen05_mma_bar_sync_before_completion_orders_nothing"
        )),
        AnalysisConfig::new((64, 1, 1)),
    );
    assert_any(
        &ws,
        "warp 1's read of D at lane 32 after the MMA's write",
        |w| {
            w.kind == ConflictKind::WriteRead
                && w.cell.lane == 32
                && w.earlier == Side::effect(0, Write, AsyncOpKind::Tcgen05Mma)
                && warp(w.later.thread) == 1
        },
    );
}

/// The same `bar.sync` before completion with both fence roles present (the commit's before
/// role, warp 1's `after_thread_sync`) is still no witness: no path from the MMA to warp 1's
/// read passes through an observation of its completion.

fn test_tcgen05_mma_bar_sync_between_issue_and_commit_orders_nothing() {
    let ws = unproved(
        &parse(&ptx!(
            "execution_error/tcgen05_mma_bar_sync_between_issue_and_commit_orders_nothing"
        )),
        AnalysisConfig::new((64, 1, 1)),
    );
    assert_any(&ws, "thread 32's read of D before the MMA's write", |w| {
        w.kind == ConflictKind::ReadWrite
            && w.cell.lane == 32
            && w.earlier.thread == 32
            && w.earlier.mode == Read
            && w.later == Side::effect(0, Write, AsyncOpKind::Tcgen05Mma)
    });
}

/// Warp 1 waits on `mma_bar` and then reads `D` without `tcgen05.fence::after_thread_sync`: the
/// commit supplies the before role, nothing the after role. With the fence, the same kernel is
/// accepted (`test_tcgen05_mma_every_reader_waiting_is_accepted`).

fn test_tcgen05_mma_bar_sync_reader_without_fence_after_thread_sync_is_rejected() {
    let ws = unproved(
        &parse(&ptx!(
            "execution_error/tcgen05_mma_bar_sync_reader_without_fence_after_thread_sync_is_rejected"
        )),
        AnalysisConfig::new((64, 1, 1)),
    );
    assert_any(
        &ws,
        "warp 1's read of D at lane 32 after the MMA's write",
        |w| {
            w.kind == ConflictKind::WriteRead
                && w.cell.lane == 32
                && w.earlier == Side::effect(0, Write, AsyncOpKind::Tcgen05Mma)
                && w.later == Side::effect(32, Read, AsyncOpKind::Tcgen05Ld)
        },
    );
}

/// One warp seeds `D` with `tcgen05.st` and `tcgen05.wait::st`, then thread 0's MMA reads and
/// overwrites it after a `bar.sync`, with no `tcgen05` fence. With the fences, the same kernel
/// is accepted (`test_tcgen05_mma_decodes_raw_operand_and_accumulator_bits`).

fn test_tcgen05_mma_fenced_bar_sync_before_completion_orders_nothing() {
    let ws = unproved(
        &parse(&ptx!(
            "execution_error/tcgen05_mma_fenced_bar_sync_before_completion_orders_nothing"
        )),
        AnalysisConfig::new((64, 1, 1)),
    );
    assert_any(
        &ws,
        "warp 1's read of D at lane 32 after the MMA's write",
        |w| {
            w.kind == ConflictKind::WriteRead
                && w.cell.lane == 32
                && w.earlier == Side::effect(0, Write, AsyncOpKind::Tcgen05Mma)
                && w.later.mode == Read
                && w.later.op == Some(AsyncOpKind::Tcgen05Ld)
                && warp(w.later.thread) == 1
        },
    );
}

/// Warp 0 reads `D` right after the commit, without waiting and without an after-fence.

fn test_tcgen05_mma_operand_write_after_bar_sync_is_an_inflight_hazard() {
    let ws = conflicts(
        &parse(&ptx!(
            "execution_error/tcgen05_mma_operand_write_after_bar_sync_is_an_inflight_hazard"
        )),
        AnalysisConfig::new((64, 1, 1)),
    );
    assert_any(&ws, "thread 32's write after the MMA's read of A", |w| {
        on_shared(w)
            && w.earlier == Side::effect(0, Read, AsyncOpKind::Tcgen05Mma)
            && w.later == Side::plain(32, Write)
    });
}

/// Reading one's own `cp.async` destination before `wait_group` conflicts with the copy even
/// on one thread: the copy's write is an async effect, outside the issuer's program order.

fn test_tcgen05_mma_read_after_commit_without_waiting_is_an_inflight_hazard() {
    let ws = unproved(
        &parse(&ptx!(
            "execution_error/tcgen05_mma_read_after_commit_without_waiting_is_an_inflight_hazard"
        )),
        AnalysisConfig::new((64, 1, 1)),
    );
    assert_any(&ws, "a quadrant-0 read after the MMA's write of D", |w| {
        w.cell.lane < 32
            && w.earlier == Side::effect(0, Write, AsyncOpKind::Tcgen05Mma)
            && w.later.mode == Read
    });
}

/// Warp 1 reads `D` before the MMA is issued; a `bar.sync` between issue and commit is no
/// witness for the read-then-write pair.

fn test_tcgen05_mma_reader_without_fence_after_thread_sync_is_rejected() {
    let ws = unproved(
        &parse(&ptx!(
            "execution_error/tcgen05_mma_reader_without_fence_after_thread_sync_is_rejected"
        )),
        AnalysisConfig::new((64, 1, 1)),
    );
    assert_any(
        &ws,
        "warp 1's read of D at lane 32 after the MMA's write",
        |w| {
            w.kind == ConflictKind::WriteRead
                && w.cell.lane == 32
                && w.earlier == Side::effect(0, Write, AsyncOpKind::Tcgen05Mma)
                && w.later == Side::effect(32, Read, AsyncOpKind::Tcgen05Ld)
        },
    );
}

/// Warp 1 skips the wait: warp 0's `bar.sync` after the completion carries the order to it, but
/// it reads `D` without `tcgen05.fence::after_thread_sync`. With the fence, the same kernel is
/// accepted (`test_tcgen05_mma_bar_sync_after_completion_orders_the_read`).

fn test_tcgen05_relinquish_unordered_with_other_warps_alloc() {
    let checked = check(
        &parse(&ptx!(
            "execution_error/tcgen05_relinquish_unordered_with_other_warps_alloc"
        )),
        None,
        AnalysisConfig::new((64, 1, 1)),
    );
    let graph = &checked.analysis.graph;
    let thread = |e| {
        graph
            .acting_thread(e)
            .expect("an allocation and a relinquish act for a thread")
            .0
    };
    let pairs: Vec<(u32, u32)> = checked
        .report
        .allocation_permit
        .violations()
        .iter()
        .map(|v| (thread(v.allocation), thread(v.relinquish)))
        .collect();
    assert_eq!(pairs, [(0, 32)], "warp 0's allocation, warp 1's relinquish");
}

fn test_tcgen05_st_then_mma_without_thread_sync_fences_is_rejected() {
    let mut config = AnalysisConfig::new((32, 1, 1));
    config.arrays = vec![ArrayDef {
        name: "out".to_string(),
        base: 0x20000,
        elem_width: 4,
        len: 1,
        kind: ArrayKind::Output,
    }];
    config.params = vec![ParamValue::ArrayPtr("out".to_string())];
    let ws = unproved(
        &parse(&ptx!(
            "execution_error/tcgen05_st_then_mma_without_thread_sync_fences_is_rejected"
        )),
        config,
    );
    for (kind, mode) in [
        (ConflictKind::WriteRead, Read),
        (ConflictKind::WriteWrite, Write),
    ] {
        assert_any(
            &ws,
            &format!("thread 1's store to lane 1 before the MMA's {mode:?} of D"),
            |w| {
                w.kind == kind
                    && w.cell.lane == 1
                    && w.earlier == Side::effect(1, Write, AsyncOpKind::Tcgen05St)
                    && w.later == Side::effect(0, mode, AsyncOpKind::Tcgen05Mma)
            },
        );
    }
}

fn test_tcgen05_wait_ld_after_bar_sync_is_rejected() {
    let allocs = never_freed(
        &parse(&ptx!(
            "execution_error/tcgen05_wait_ld_after_bar_sync_is_rejected"
        )),
        AnalysisConfig::new((32, 1, 1)),
    );
    assert_eq!(
        allocs,
        vec![(0, 32)],
        "expected warp 0's allocation never freed"
    );
}

/// Same for a `tcgen05.wait::st` after an `mbarrier.arrive`.

fn test_tcgen05_wait_st_after_mbarrier_arrive_is_rejected() {
    let allocs = never_freed(
        &parse(&ptx!(
            "execution_error/tcgen05_wait_st_after_mbarrier_arrive_is_rejected"
        )),
        AnalysisConfig::new((32, 1, 1)),
    );
    assert_eq!(
        allocs,
        vec![(0, 32)],
        "expected warp 0's allocation never freed"
    );
}

fn test_tensormap_replace_while_tma_in_flight() {
    let ws = conflicts(
        &ptx!(parse "execution_error/tensormap_replace_while_tma_in_flight"),
        tma_config(32),
    );
    assert_any(
        &ws,
        "the TMA's read unordered with the later replace",
        |w| {
            w.kind == ConflictKind::ReadWrite
                && w.location.space == Space::Global
                && w.earlier == Side::effect(0, Read, AsyncOpKind::TensorCopy)
                && w.later == Side::plain(0, Write)
        },
    );
}

/// A `try_cancel` response is an async write ordered only by a waiter observing its
/// mbarrier: warp 1 reads it after `bar.sync` alone and conflicts with the write.

fn test_tma_acquires_another_tensor_map() {
    assert_tensor_map_read_uncovered(
        &ptx!(parse "execution_error/tma_acquires_another_tensor_map"),
        MissingFence::TensormapAcquire,
    );
}

fn test_tma_uses_another_warps_cp_fenceproxy_copy_without_sync() {
    let ws = conflicts(
        &ptx!(parse "execution_error/tma_uses_another_warps_cp_fenceproxy_copy_without_sync"),
        tma_config(64),
    );
    assert_any(&ws, "warp 0's copy unordered with thread 32's TMA", |w| {
        w.kind == ConflictKind::WriteRead
            && w.location.space == Space::Global
            && w.earlier == Side::plain(0, Write)
            && w.later == Side::effect(32, Read, AsyncOpKind::TensorCopy)
    });
}

/// The copy reads its tensor map asynchronously, until its completion is observed: rewriting
/// the map before waiting races with that read.

fn test_tma_uses_tensormap_built_by_other_thread_without_sync() {
    let ws = conflicts(
        &ptx!(parse "execution_error/tma_uses_tensormap_built_by_other_thread_without_sync"),
        tma_config(64),
    );
    assert_any(
        &ws,
        "thread 0's replace unordered with thread 32's TMA",
        |w| {
            w.kind == ConflictKind::WriteRead
                && w.location.space == Space::Global
                && w.earlier == Side::plain(0, Write)
                && w.later == Side::effect(32, Read, AsyncOpKind::TensorCopy)
        },
    );
}

/// Warp 0 publishes the tensor map with `tensormap.cp_fenceproxy`, whose release is there, and
/// thread 32 acquires it, but nothing orders the copy before thread 32's TMA.

fn test_tma_without_tensormap_acquire_fence() {
    assert_tensor_map_read_uncovered(
        &ptx!(parse "execution_error/tma_without_tensormap_acquire_fence"),
        MissingFence::TensormapAcquire,
    );
}

/// Thread 0 replaces the tensor map's fields in global memory and acquires it, with no release
/// between its writes and the acquire.

fn test_tma_without_tensormap_release_fence() {
    assert_tensor_map_read_uncovered(
        &ptx!(parse "execution_error/tma_without_tensormap_release_fence"),
        MissingFence::TensormapRelease,
    );
}

/// An acquire covers only the tensor map it names: acquiring `other` leaves the copy's read of
/// `gbl` uncovered.

fn test_cp_async_bulk_tensor_rejects_an_incomplete_tensor_map() {
    let module = ptx!(parse "failing/cp_async_bulk_tensor_rejects_an_incomplete_tensor_map");
    let mut config = AnalysisConfig::new((32, 1, 1));
    config.arrays = vec![ArrayDef {
        name: "in".to_string(),
        base: 0x10000,
        elem_width: 2,
        len: 64,
        kind: ArrayKind::Input,
    }];
    config.params = vec![ParamValue::ArrayPtr("in".to_string())];
    let err = run_kernel(&module, None, config).unwrap_err();
    match &err {
        AnalysisError::Eval(EvalError::TensorMapFieldMissing { field, .. }) => {
            assert_eq!(field, "fill_mode");
        }
        other => panic!("expected TensorMapFieldMissing, got: {}", other),
    }
}

/// Like `test_tcgen05_mma_numeric_correctness`, but `disable-output-lane`
/// masks lane 0 (PTX ISA 9.7.17.10.9.1): `D[0][0]` is never written, so the
/// `tcgen05.ld` of it reads uninitialized Tensor Memory instead of `136`.

fn test_cp_fenceproxy_by_one_lane_of_a_warp_is_rejected() {
    let module = ptx!(parse "failing/cp_fenceproxy_by_one_lane_of_a_warp_is_rejected");
    let mut config = AnalysisConfig::new((32, 1, 1));
    config.arrays = vec![
        ArrayDef {
            name: "in".to_string(),
            base: 0x10000,
            elem_width: 2,
            len: 64,
            kind: ArrayKind::Input,
        },
        ArrayDef {
            name: "out".to_string(),
            base: 0x20000,
            elem_width: 2,
            len: 2,
            kind: ArrayKind::Output,
        },
    ];
    config.params = vec![
        ParamValue::ArrayPtr("in".to_string()),
        ParamValue::ArrayPtr("out".to_string()),
    ];
    let err = run_kernel(&module, None, config).unwrap_err();
    assert!(
        matches!(
            &err,
            AnalysisError::Eval(EvalError::WarpMismatch { reason, .. })
                if reason.contains("tensormap.cp_fenceproxy is .aligned")
        ),
        "expected a warp mismatch, got: {}",
        err
    );
}

/// `cp.async.bulk.tensor` on a tensor-map missing a field (`.fill_mode`) must
/// error naming it: an incomplete map is a kernel bug, not a gap to fill with
/// a default.

fn test_tcgen05_access_past_an_allocation_into_an_adjacent_one_is_rejected() {
    let module = parse(&ptx!(
        "failing/tcgen05_access_past_an_allocation_into_an_adjacent_one_is_rejected"
    ));
    let err = run_kernel(&module, None, AnalysisConfig::new((32, 1, 1))).unwrap_err();
    assert!(
        matches!(
            err,
            AnalysisError::Eval(EvalError::Tcgen05AccessOutsideAllocation {
                start_col: 31,
                num_cols: 2,
                ..
            })
        ),
        "{err}"
    );
}

/// A `taddr` naming a lane quadrant other than the issuing warp's (PTX ISA
/// 9.7.17.8.1) must error, not be silently "corrected" by deriving the lane
/// from `ThreadId`.

fn test_tcgen05_mma_disable_output_lane_skips_the_write() {
    let module = ptx!(parse "failing/tcgen05_mma_disable_output_lane_skips_the_write");
    let mut config = AnalysisConfig::new((32, 1, 1));
    config.arrays = vec![ArrayDef {
        name: "out".to_string(),
        base: 0x20000,
        elem_width: 4,
        len: 1,
        kind: ArrayKind::Output,
    }];
    config.params = vec![ParamValue::ArrayPtr("out".to_string())];
    let err = run_kernel(&module, None, config).unwrap_err();
    assert!(
        matches!(
            err,
            AnalysisError::Eval(EvalError::Tcgen05UninitializedRead {
                lane: 0,
                col: 0,
                ..
            })
        ),
        "expected an uninitialized read of D[0][0] (lane 0 must never be written), got: {}",
        err
    );
}

/// Only `.kind::f16` and `.kind::f8f6f4` are modeled; other kinds are
/// rejected at lowering naming the rejected and modeled kinds, not the
/// generic "not yet implemented".

fn test_tcgen05_mma_rejects_a_d_address_off_lane_0() {
    for (lane, src) in [
        (32, ptx!("failing/tcgen05_mma_encoding_d_lane32")),
        (128, ptx!("failing/tcgen05_mma_encoding_d_lane128")),
    ] {
        match run_tcgen05_mma(&src) {
            Err(AnalysisError::Eval(EvalError::Unsupported { what, .. })) => {
                let needle = format!("[d-tmem] at lane {lane}");
                assert!(what.contains(&needle), "expected {needle:?} in: {what}");
            }
            Err(other) => panic!("lane {lane}: expected Unsupported, got: {other}"),
            Ok(_) => panic!("lane {lane}: expected Unsupported, got Ok"),
        }
    }
}

/// PTX ISA Table 65: for 8- and 16-bit operands a transposed matrix may
/// use every swizzling mode except 128B with 32B atomicity.

fn test_tcgen05_mma_rejects_a_d_address_off_lane_0() {
    for (lane, src) in [
        (32, ptx!("failing/tcgen05_mma_encoding_d_lane32")),
        (128, ptx!("failing/tcgen05_mma_encoding_d_lane128")),
    ] {
